const q=s=>document.querySelector(s);q("#form").addEventListener("submit",async e=>{e.preventDefault();const b=e.submitter,s=q("#status");b.disabled=true;s.textContent="Creando…";try{const r=await fetch("/api/bootstrap",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({token:q("#token").value,name:q("#name").value,email:q("#email").value,password:q("#password").value})});const d=await r.json();if(!r.ok)throw new Error(d.message||d.error||"No se pudo crear la cuenta.");location.href="/campus/admin.html";}catch(err){s.textContent=err.message;b.disabled=false;}});